const body = $('Gatilho').item.json.body || {};
const ctx = $('Buscar Contexto Site').item.json || {};
const msg = String(body.message || '').toLowerCase();
const mensagens = [];
const product = Array.isArray(ctx.products) && ctx.products.length ? ctx.products[0] : null;
const order = Array.isArray(ctx.orders) && ctx.orders.length ? ctx.orders[0] : null;
const promos = Array.isArray(ctx.promotions) ? ctx.promotions : [];

const money = (v) => `R$ ${Number(v || 0).toFixed(2).replace('.', ',')}`;

if (order && /(pedido|status|entrega|compra)/.test(msg)) {
  mensagens.push(`Encontrei o pedido ${order.orderCode}. Status atual: ${order.status}. Pagamento: ${order.paymentStatus}.`);
  if (order.items?.length) mensagens.push(`Itens do pedido: ${order.items.map(i => `${i.quantity || 1}x ${i.productName || i.name || 'item'}`).join(', ')}.`);
} else if (product) {
  if (product.sobConsulta) {
    mensagens.push(`O produto ${product.name} está com preço sob consulta no momento.`);
  } else {
    mensagens.push(`O produto ${product.name} está por ${money(product.price)}.`);
  }
  if (product.category) mensagens.push(`Categoria: ${product.category}.`);
  if (product.stockLevel !== undefined && product.stockLevel !== null) mensagens.push(`Estoque atual: ${product.stockLevel}.`);
  if (promos.length) mensagens.push(`Também encontrei ${promos.length} promoção(ões) ativa(s) relacionada(s) no sistema.`);
} else if (ctx.customer) {
  mensagens.push(`Encontrei seu cadastro no sistema Terra Fort e posso seguir com informações do atendimento.`);
} else {
  mensagens.push('Recebi sua solicitação pelo site da Terra Fort e já consultei o sistema.');
  mensagens.push('Se você me disser o produto, pedido ou dúvida específica, consigo responder com base nos dados atuais da loja.');
}

return [{ json: { output: { mensagens } } }];

